<script setup>
import{computed,onMounted,ref,watch}from'vue';import{teacherApi,formatTime}from'../api/teacher';import{candidateNames}from'../utils/examLifecycle'
const props=defineProps({examId:{required:true},draft:Boolean}),rows=ref([]),filter=ref('ALL'),error=ref('');const filters=[['ALL','全部'],['NOT_ENTERED','未进入'],['IN_PROGRESS','答题中'],['PENDING_REVIEW','待阅'],['AUTO_GRADED','已自动评分'],['REVIEWED','已阅'],['ABSENT','缺考']];const visible=computed(()=>filter.value==='ALL'?rows.value:rows.value.filter(row=>row.candidateStatus===filter.value));async function load(){try{rows.value=(await teacherApi.examCandidates(props.examId)).data}catch(e){error.value=e.message}}onMounted(load);watch(()=>props.examId,load)
</script>
<template><p v-if="error" class="error-message">{{error}}</p><p v-if="draft" class="empty-state">考试发布后将冻结应考学生名单。</p><template v-else><div class="filter-tabs"><button v-for="item in filters" :key="item[0]" :class="{active:filter===item[0]}" @click="filter=item[0]">{{item[1]}}</button></div><p v-if="!visible.length" class="empty-state">当前筛选条件下暂无考生。</p><div v-else class="table-scroll"><table><thead><tr><th>学生</th><th>账号</th><th>考试状态</th><th>交卷方式 / 时间</th><th>阅卷状态</th><th>最终成绩</th></tr></thead><tbody><tr v-for="row in visible" :key="row.studentId"><td><strong>{{row.studentName}}</strong></td><td>{{row.username}}</td><td><span :class="['badge',row.candidateStatus]">{{candidateNames[row.candidateStatus]||row.candidateStatus}}</span></td><td>{{row.submissionStatus==='AUTO_SUBMITTED'?'自动交卷':row.submittedAt?'主动交卷':'—'}}<small>{{formatTime(row.submittedAt||row.enteredAt)}}</small></td><td>{{row.candidateStatus==='REVIEWED'?'已阅':row.candidateStatus==='PENDING_REVIEW'?'待阅':row.candidateStatus==='AUTO_GRADED'?'已自动评分':'—'}}</td><td>{{row.totalScore??'—'}}<small v-if="row.resultsReleased">成绩已发布</small></td></tr></tbody></table></div></template></template>
